.tagify {
  --tags-disabled-bg: #00000099 !important;
  --tags-border-color: #00000000 !important;
  --tags-hover-border-color: #00000000 !important;
  --tags-focus-border-color: #536dfe !important;
  --tag-bg: #00000000 !important;
