  --tag-remove-btn-bg--hover: #ff2d55 !important;
  --placeholder-color: #00000000 !important;
  --placeholder-color-focus: #00000000 !important;
}

0% {
  background: linear-gradient(45deg,var(--tag-bg) 25%,transparent 25%,transparent 50%,var(--tag-bg) 50%,var(--tag-bg) 75%,transparent 75%,transparent) 0/5px 5px !important;
}

.tagify--loading .tagify__input::after {
  border-color: #00000099 #ffffff38 #ffffff38 transparent !important;
}

.tagify__tag--loading::after {
  border-color: #00000099 #ffffff38 #ffffff38 transparent !important;
}

.tagify__tag__removeBtn:hover {
  color: #ffffff !important;
}

.tagify__tag__removeBtn:hover+div::before {
  box-shadow: 0 0 0 var(--tag-inset-shadow-size) var(--tag-remove-bg,#ff2d554c) inset!important !important;
}

.tagify__input:last-child:focus:empty::before {
